/**
 * Expo config plugin: let a tap on the Android home-screen widget open the app.
 *
 * Why: expo-widgets (SDK 58) renders Android widgets with Glance and turns a widget
 * Button into a broadcast to the widget's own receiver (`<Name>Provider`, generated by
 * its plugin as a one-line subclass of `ExpoWidgetsAppWidgetProvider`). That receiver
 * only re-renders the widget and tells the app if it happens to be running; there is
 * no way to open the app or a URL from an Android widget.
 *
 * This plugin rewrites that generated subclass (same class name, so expo-widgets still
 * finds it) to override `onReceive`: when the tapped Button's `target` is a link in the
 * app's own scheme (`buaic://…`), it opens that link in the app (an ACTION_VIEW intent
 * limited to this package, handled by Expo Router); every other interaction goes to
 * expo-widgets unchanged. No permission, no new manifest entry.
 *
 * It runs as a finalized mod, i.e. after every plugin's dangerous mods, so it always
 * overwrites the file expo-widgets has just written, whatever the plugin order.
 */
const fs = require('fs');
const path = require('path');
const { AndroidConfig, withFinalizedMod } = require('expo/config-plugins');

// Must match expo-widgets' WidgetInteractionAction.kt (checked by plugins/__tests__).
const INTERACTION_ACTION = 'expo.modules.widgets.ACTION_WIDGET_INTERACTION';
const TARGET_EXTRA = 'expo.modules.widgets.extra.TARGET';

function providerSource(androidPackage, widgetName, scheme) {
  return `package ${androidPackage}

import android.content.Context
import android.content.Intent
import android.net.Uri
import android.util.Log
import expo.modules.widgets.ExpoWidgetsAppWidgetProvider

// Generated by plugins/withWidgetDeepLink.js (replaces the expo-widgets default).
// A tap on a widget Button whose target is a ${scheme}:// link opens that link in the app;
// any other interaction is handled by expo-widgets as usual.
class ${widgetName}Provider : ExpoWidgetsAppWidgetProvider(${JSON.stringify(widgetName)}) {
  override fun onReceive(context: Context, intent: Intent) {
    val target = if (intent.action == INTERACTION_ACTION) intent.getStringExtra(TARGET_EXTRA) else null
    if (target != null && target.startsWith(LINK_PREFIX)) {
      val open = Intent(Intent.ACTION_VIEW, Uri.parse(target))
        .setPackage(context.packageName)
        .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
      try {
        context.startActivity(open)
      } catch (error: Exception) {
        Log.w("BuaicWidget", "Could not open \$target", error)
      }
      return
    }
    super.onReceive(context, intent)
  }

  private companion object {
    const val INTERACTION_ACTION = ${JSON.stringify(INTERACTION_ACTION)}
    const val TARGET_EXTRA = ${JSON.stringify(TARGET_EXTRA)}
    const val LINK_PREFIX = ${JSON.stringify(`${scheme}://`)}
  }
}
`;
}

function withWidgetDeepLink(config, props = {}) {
  const widgetName = props.widgetName;
  const scheme = props.scheme ?? (Array.isArray(config.scheme) ? config.scheme[0] : config.scheme);
  if (!widgetName || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(widgetName)) {
    throw new Error('withWidgetDeepLink: pass { widgetName } matching the expo-widgets widget name.');
  }
  if (!scheme || !/^[a-z][a-z0-9+.-]*$/.test(scheme)) {
    throw new Error('withWidgetDeepLink: the app needs a URL scheme (app.json "scheme").');
  }

  return withFinalizedMod(config, [
    'android',
    async (cfg) => {
      const androidPackage = AndroidConfig.Package.getPackage(cfg);
      const file = path.join(
        cfg.modRequest.platformProjectRoot,
        'app/src/main/java',
        ...androidPackage.split('.'),
        `${widgetName}Provider.kt`
      );
      if (!fs.existsSync(file)) {
        throw new Error(
          `withWidgetDeepLink: ${file} was not generated. Is expo-widgets configured with "enableAndroid": true and a widget named "${widgetName}"?`
        );
      }
      fs.writeFileSync(file, providerSource(androidPackage, widgetName, scheme));
      return cfg;
    },
  ]);
}

module.exports = withWidgetDeepLink;
module.exports.providerSource = providerSource;
module.exports.INTERACTION_ACTION = INTERACTION_ACTION;
module.exports.TARGET_EXTRA = TARGET_EXTRA;
